export const ensureAllDatasets = (frequencies, assembly) => {
  if (!frequencies) {
    return [];
  }

  const datasets = ((assembly) => {
    switch (assembly) {
      case "GRCh37":
        return [
          "gem_j_wga",
          "jga_wes",
          "jga_snp",
          "tommo",
          "hgvd",
          "gnomad_genomes",
          "gnomad_exomes",
        ];
      case "GRCh38":
        return [
          "gem_j_wga",
          "jga_wgs",
          "jga_wes",
          "jga_snp",
          "tommo",
          "tommo_jsv1",
          "ncbn",
          "bbj1k",
          "bbj2k",
          "jogo",
          "gnomad_genomes",
          "gnomad_exomes",
        ];
    }
  })(assembly);

  return datasets.map(
    (source) =>
      frequencies.find((x) => x.source === source) || { source: source },
  );
};

